"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[83951],{3331:(e,r,n)=>{n.d(r,{R:()=>s,x:()=>a});var t=n(36672);const i={},o=t.createContext(i);function s(e){const r=t.useContext(o);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),t.createElement(o.Provider,{value:r},e.children)}},39863:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>m,frontMatter:()=>s,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/03/31","title":"2023-03-31","description":"Lovforslag om forbud i USA giver anledning til bekymring for VPN og TikTok","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/da/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31. marts 2023","top_news":"Lovforslag om forbud i USA giver anledning til bekymring for VPN og TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/da/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/da/2023/03/30"}}');var i=n(23420),o=n(3331);const s={localized_date:"31. marts 2023",top_news:"Lovforslag om forbud i USA giver anledning til bekymring for VPN og TikTok"},a="2023-03-31",l={},d=[{value:"Lovforslag om forbud i USA giver anledning til bekymring for VPN og TikTok",id:"lovforslag-om-forbud-i-usa-giver-anledning-til-bekymring-for-vpn-og-tiktok",level:2},{value:"Blandede holdninger til Y Combinators v\xe6rdi for startups",id:"blandede-holdninger-til-y-combinators-v\xe6rdi-for-startups",level:2},{value:"Scratch: Popul\xe6rt visuelt programmeringssprog for b\xf8rn",id:"scratch-popul\xe6rt-visuelt-programmeringssprog-for-b\xf8rn",level:2},{value:"Udfordringer og afvejninger inden for LED-belysningsteknologi",id:"udfordringer-og-afvejninger-inden-for-led-belysningsteknologi",level:2},{value:"Over halvdelen af nye NPM-pakker er spam",id:"over-halvdelen-af-nye-npm-pakker-er-spam",level:2},{value:"USA frems\xe6tter lovforslag med trusler mod teknisk frihed og privatlivets fred",id:"usa-frems\xe6tter-lovforslag-med-trusler-mod-teknisk-frihed-og-privatlivets-fred",level:2},{value:"Open-Source 3D Rendering Engine for Education &amp; Integration",id:"open-source-3d-rendering-engine-for-education--integration",level:2},{value:"Google ben\xe6gter at have brugt OpenAI&#39;s ChatGPT til at tr\xe6ne Bard",id:"google-ben\xe6gter-at-have-brugt-openais-chatgpt-til-at-tr\xe6ne-bard",level:2},{value:"Twitter API negligeret, brugernes utilfredshed vokser",id:"twitter-api-negligeret-brugernes-utilfredshed-vokser",level:2},{value:"San Jose Police Union Director anklaget for narkosmugling",id:"san-jose-police-union-director-anklaget-for-narkosmugling",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-03-31",children:"2023-03-31"})}),"\n",(0,i.jsx)(r.h2,{id:"lovforslag-om-forbud-i-usa-giver-anledning-til-bekymring-for-vpn-og-tiktok",children:"Lovforslag om forbud i USA giver anledning til bekymring for VPN og TikTok"}),"\n",(0,i.jsxs)(r.p,{children:["Et amerikansk lovforslag om forbud, der st\xf8ttes af Det Hvide Hus og har til form\xe5l at regulere internettet, kan g\xf8re VPN'er ulovlige, give b\xf8der p\xe5 op til 1 million dollars og 20 \xe5rs f\xe6ngsel og ses som et angreb p\xe5 borgerrettighederne. Lovforslaget har st\xf8tte fra begge partier og fokuserer p\xe5 nationale sikkerhedshensyn i forbindelse med Kina og begr\xe6nsning af forretningsforbindelser med landet. EU f\xf8lger m\xe5ske ikke trop med USA's tendens, da landene har deres egen juridiske struktur, og TikToks forbud kan f\xf8re til vrede blandt unge mennesker og geng\xe6ldelse mod den amerikanske regering. Forbuddets kritikere h\xe6vder, at det truer den enkeltes privatliv og ytrings- og ytringsfriheden.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"blandede-holdninger-til-y-combinators-v\xe6rdi-for-startups",children:"Blandede holdninger til Y Combinators v\xe6rdi for startups"}),"\n",(0,i.jsxs)(r.p,{children:["Der er delte meninger om Y Combinators (YC) v\xe6rdi for nystartede virksomheder, afh\xe6ngigt af individuelle perspektiver og behov. Mens nogle s\xe6tter pris p\xe5 YC's netv\xe6rk og mentorater, kritiserer andre YC's r\xe5dgivning og fokus p\xe5 kortsigtede m\xe5l. YC's omd\xf8mme og brand kan hj\xe6lpe med fundraising, men dets ubegr\xe6nsede SAFE-aftale og v\xe6gt p\xe5 at skalere for enhver pris passer m\xe5ske ikke til alle stiftere. Betydningen af f\xe6llesskabsopbygning og personlige forbindelser i et format, der kun er baseret p\xe5 fjernadgang, er ogs\xe5 omdiskuteret. I sidste ende afh\xe6nger v\xe6rdien af YC af en stifters evne til at udnytte YC's ressourcer for at maksimere chancerne for succes.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"scratch-popul\xe6rt-visuelt-programmeringssprog-for-b\xf8rn",children:"Scratch: Popul\xe6rt visuelt programmeringssprog for b\xf8rn"}),"\n",(0,i.jsxs)(r.p,{children:["Scratch er et popul\xe6rt visuelt programmeringssprog rettet mod b\xf8rn, som bruger farverige blokke i stedet for tekstbaseret kodning for at hj\xe6lpe dem med at l\xe6re programmeringsbegreber. Programmet indeholder grundl\xe6ggende programmeringsprincipper som f.eks. variabler, lister, if/else- og looping-kontrolflowstrukturer og begivenhedsbaseret samtidighed. Scratch har en enkel og brugervenlig tilgang, der tilskynder b\xf8rn til at udforske beregning p\xe5 en kreativ m\xe5de, samt et stort fokus p\xe5 interaktion med ligestillede og deling af arbejde for at f\xe5 feedback. Scratch-f\xe6llesskabet er et af de st\xf8rste kodningsf\xe6llesskaber i verden med over 103 millioner brugere og 123 millioner projekter, der er delt p\xe5 platformen. Selv om der er bekymringer vedr\xf8rende uregulerede sociale medier og b\xf8rn, der spiller videospil i stedet for at bruge Scratch til undervisningsform\xe5l, har v\xe6rkt\xf8jet inspireret mange til at interessere sig for programmering, med projekter, der sp\xe6nder fra begynderkodning til avancerede programmeringsf\xe6rdigheder.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"udfordringer-og-afvejninger-inden-for-led-belysningsteknologi",children:"Udfordringer og afvejninger inden for LED-belysningsteknologi"}),"\n",(0,i.jsxs)(r.p,{children:["LED-p\xe6rer har udfordringer med hurtige fejl, d\xe5rlig farvegengivelse og spektral lighed, d\xe5rligt konstruerede str\xf8mforsyninger, overophedning og h\xf8jere omkostninger til indend\xf8rs belysning. Konstantstr\xf8mforsyninger er n\xf8dvendige for LED-belysning, og armaturerne skal konstrueres anderledes end gl\xf8dep\xe6rer for at kunne aflede varmen. Der er bekymringer om LED-p\xe6rers p\xe5lidelighed og holdbarhed, selv om der findes h\xf8jkvalitetsl\xf8sninger til en h\xf8jere pris. Det er en udfordring at integrere LED-p\xe6rer med lysd\xe6mperenheder og sikre kompatibilitet. LED-belysningens flimren og manglende livlighed har f\xf8rt til udvikling af nye klassificeringssystemer og indstillelige LED-p\xe6rer. Generelt set har LED-teknologien potentiale, men kr\xe6ver fortsat udvikling og innovation.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"over-halvdelen-af-nye-npm-pakker-er-spam",children:"Over halvdelen af nye NPM-pakker er spam"}),"\n",(0,i.jsxs)(r.p,{children:["Over halvdelen af de nye indsendte npm-pakker er spam, og mange indeholder links til ondsindede websteder eller tilbyder falske freebies som Fortnite V-Bucks. Stigningen af spam menes at v\xe6re forbundet med coding boot camps, hvor studerende opfordres til at udgive pakker, selv om de ikke g\xf8r noget. Respondenterne har foresl\xe5et l\xf8sninger som automatiserede testprocesser og en web-of-trust-model. Sp\xf8rgsm\xe5let fremh\xe6ver den komplekse karakter af etik i softwareudviklingsindustrien og sp\xe6ndinger mellem ytringsfrihed og privat ejendomsret. Sikkerhedsforskere har identificeret tilstedev\xe6relsen af spam-pakker i hele npm-registret og er i gang med at unders\xf8ge sagen n\xe6rmere.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"usa-frems\xe6tter-lovforslag-med-trusler-mod-teknisk-frihed-og-privatlivets-fred",children:"USA frems\xe6tter lovforslag med trusler mod teknisk frihed og privatlivets fred"}),"\n",(0,i.jsxs)(r.p,{children:['Den amerikanske regering har foresl\xe5et et lovforslag, der vil give hidtil usete bef\xf8jelser til at forbyde enhver udenlandsk teknologi, som den anser for at v\xe6re en "trussel mod den nationale sikkerhed", hvilket f\xe5r nogle til at h\xe6vde, at det kan f\xf8re til Kina-lignende censurbef\xf8jelser og v\xe6re meget bredere end oprindeligt antaget. Der er ogs\xe5 debat om forbuddet mod kinesisk ejede sociale medieapps, hvor nogle h\xe6vder, at det er en glidebane i retning af censurering af oplysninger, mens andre h\xe6vder, at det er n\xf8dvendigt for at forhindre kinesiske virksomheder i at stj\xe6le amerikansk teknologi og indsamle oplysninger til spionageform\xe5l. RESTRICT Act er et lovforslag, der kan bruges til at forbyde TikTok og VPN-tjenester, og kritikere h\xe6vder, at det kan v\xe6re i strid med det f\xf8rste till\xe6g til forfatningsloven. Republikanske senatorer har ogs\xe5 foresl\xe5et at forbyde f\xf8derale ansatte at bruge apps til sociale medier, der ejes af kinesiske virksomheder, p\xe5 grund af bekymringer om spionage og overv\xe5gning. Nogle kommentatorer mener, at lovgivningen er udtryk for protektionisme fra regeringens side, mens andre h\xe6vder, at v\xe6ksten i de sociale medier skader den mentale sundhed og bidrager til manipulation af den offentlige mening.\n',(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"open-source-3d-rendering-engine-for-education--integration",children:"Open-Source 3D Rendering Engine for Education & Integration"}),"\n",(0,i.jsxs)(r.p,{children:["En udvikler har frigivet en StratusGFX 3D-renderingsmotor med \xe5ben kildekode, s\xe5 folk kan integrere dens renderingskode i andre motorer eller bruge den som en uddannelsesressource. Dens muligheder omfatter realtidsreflektioner, skygger og fuld PBR-skyggeunderst\xf8ttelse, men den underst\xf8tter i \xf8jeblikket kun OpenGL. Skaberen overvejer at portere rendereren til Vulkan for at forbedre kompatibiliteten p\xe5 tv\xe6rs af platforme. StratusGFX-motoren er designet til at maksimere realismen, men med fallback-kompromisfunktioner til mindre kraftfuld hardware, og dens arkitektur er tilg\xe6ngelig p\xe5 Github til Windows og Linux. Motoren er i pre-release/beta-release, og der b\xf8r forventes betydelige fejl og ustabilitet.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"google-ben\xe6gter-at-have-brugt-openais-chatgpt-til-at-tr\xe6ne-bard",children:"Google ben\xe6gter at have brugt OpenAI's ChatGPT til at tr\xe6ne Bard"}),"\n",(0,i.jsxs)(r.p,{children:["Google ben\xe6gter at have brugt OpenAI's ChatGPT til at tr\xe6ne Bard, en ny sprogmodel. Der er blevet rejst bekymring om det etiske i at tr\xe6ne en stor sprogmodel med output fra en anden kommercielt kontrolleret LLM. OpenAI's servicevilk\xe5r forbyder tr\xe6ning af konkurrerende modeller via OpenAI's ML-output, men Google er ikke bundet af dette. En tidligere Google-medarbejder har h\xe6vdet, at de har brugt OpenAI-data, men Google ben\xe6gter dette. AI-genereret materiale er ikke ophavsretligt beskyttet, og det er tilladt at tr\xe6ne p\xe5 andre modeloutputs. Nogle h\xe6vder, at det kan v\xe6re moralsk berettiget at stj\xe6le fra ChatGPT, da det var gruppesourcet, men at tr\xe6ning af modeller p\xe5 andre AI-genererede data kan h\xe5ndh\xe6ve d\xe5rlige data.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"twitter-api-negligeret-brugernes-utilfredshed-vokser",children:"Twitter API negligeret, brugernes utilfredshed vokser"}),"\n",(0,i.jsxs)(r.p,{children:["Twitter API'et bliver angiveligt ikke vedligeholdt, hvilket f\xf8rer til ustabilitetsproblemer for brugerne. Nogle brugere har rapporteret, at de f\xf8ler sig fremmedgjort fra tjenesten p\xe5 grund af det faldende indhold af videnskabelige artikler og den \xf8gede andel af provokerende eller st\xf8dende indhold. Mange sociale medieplatforme anvender algoritmiske feeds, men standardindstillinger er vigtige, da de p\xe5virker brugernes adf\xe6rd. Twitter-brugere oplever problemer s\xe5som interne serverfejl og problemer med at f\xe5 adgang til webstedet, hvilket har f\xe5et nogle til at skifte til alternative platforme s\xe5som Mastodon. Twitters nylige problemer med ustabilitet har f\xe5et nogle brugere til at reducere deres brug. P\xe5 trods af disse bekymringer mener nogle, at Twitters v\xe6kst under Musks ledelse tyder p\xe5, at platformen fortsat vil blomstre, med eller uden sine hengivne brugere. Elon Musks beslutning om at begr\xe6nse adgangen til Twitters API er kontroversiel, og kritikere beskylder ham for bevidst at k\xf8re Twitter i s\xe6nk. Twitters API er nu reelt set ikke vedligeholdt, og kun \xe9n medarbejder skriver regelm\xe6ssigt p\xe5 Twitter Developers-forummet og fokuserer udelukkende p\xe5 Ads API'et.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"san-jose-police-union-director-anklaget-for-narkosmugling",children:"San Jose Police Union Director anklaget for narkosmugling"}),"\n",(0,i.jsxs)(r.p,{children:["Den administrerende direkt\xf8r for San Jose Police Officers Association, Sonia Rosa Segovia, er blevet anklaget for at have smuglet fentanyl ind i USA og for at have drevet en narkotikahandel delvist ud fra kontoret. Segovia brugte angiveligt foreningens adresse til at sende pakker til kunder og dr\xf8ftede politiforretninger med sine leverand\xf8rer. Mindst en af hendes kunder d\xf8de af en overdosis, og hun st\xe5r over for flere narkotikarelaterede anklager. Andre sager om politibetjente, der er involveret i narkohandel, har rejst sp\xf8rgsm\xe5l om retsh\xe5ndh\xe6velsens rolle i den ulovlige narkotikahandel, og nogle foresl\xe5r legalisering som en l\xf8sning. Samtalen om legalisering af narkotika ber\xf8rer ogs\xe5 eksterne virkninger og behovet for st\xf8ttesystemer. En administrerende direkt\xf8r for politiforeningen i San Jose, Joanne Southerland, er ogs\xe5 blevet anklaget for narkotikasmugling, ligesom Joanne Segovia, en ansat i politiforeningen, er blevet tiltalt for at have importeret methamfetamin til USA. Disse sager understreger behovet for l\xf8sninger til bek\xe6mpelse af narkotikasmugling og -afh\xe6ngighed, herunder kulturelle \xe6ndringer og en m\xe5lrettet indsats for retsh\xe5ndh\xe6velse.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,i.jsx)(r.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function m(e={}){const{wrapper:r}={...(0,o.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);